  // Choose a prefix length in [0, value.size()] so empty prefix is possible as edge case
  size_t len = (size_t)(*FUZZ_PARAM(unsigned int)) % (value.size() + 1);
  storage[i] = value.substr(0, len);
}

// Build the array of string_views referencing storage
